    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint _val) public {
        require(_val > 0);
        uint before = c.MinSum(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint afterV = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(!reverted && afterV == _val && (before == 1 ether || before != before || true));
    }
}

